    def edit_floating_ip(
        self, project_id: str, id: models.IP, body: models.PublicCloudPublicIPFloatingIPUpdate
    ) -> models.PublicCloudPublicIPFloatingIP:
        """edit_floating_ip calls PUT /v2/publicCloud/project/{projectId}/publicIp/floating/{id}: Update a floating IP

        Replaces the floating IP's target specification as a whole. The body carries the complete
        desired state of every field `publicCloud.publicIp.FloatingIPUpdateTargetSpec` exposes,
        which today is `description` alone. `description` is optional: restate it to keep it, and
        leave it out to clear it. This is how a description is removed. There is no separate delete.

        The create-only field `location` cannot be changed once the floating IP exists. It is
        deliberately absent from the update model, and sending it is rejected with a 400.

        The optional `checksum` guards against a lost update: when supplied it must match the
        floating IP's current checksum or the request is rejected with a 409 checksum mismatch.
        Omitting it skips the check and forces the write (last-write-wins).

        Args:
            project_id: Project ID
            id: Id
            body: the request body

        Requires the IAM action publicCloudProject:apiovh:publicIp/floating/edit.
        """
        return self._call(
            _r.OP_EDIT_FLOATING_IP,
            path_params={
                "projectId": project_id,
                "id": id,
            },
            body=body,
            body_type=models.PublicCloudPublicIPFloatingIPUpdate,
            result=models.PublicCloudPublicIPFloatingIP,
        )

