    def all_gateway_models(
        self,
        project_id: str,
        *,
        name: models.PublicCloudGatewayExternalGatewayModelEnum | str | None | NotGiven = NOT_GIVEN,
        region: str | None | NotGiven = NOT_GIVEN,
    ) -> t.Iterator[models.PublicCloudReferenceGatewayModel]:
        """all_gateway_models iterates over GET /v2/publicCloud/project/{projectId}/reference/gateway/model (List gateway models).

        It yields one item at a time, and gets the next page only when the loop reaches it.
        An error is raised and stops the loop.

        Returns the gateway models with their bandwidth in Mbit/s, read from the OVHcloud commercial
        catalog. The list holds one entry per model and region: a model sold in several regions
        appears once per region, with the bandwidth of that region and the region in `location`. The
        regions already activated on the project and those the project can activate where a model is
        sold are both listed. `location.regionActivated` on each entry tells which regions must be
        activated on the project before use. `location.availabilityZones` lists the availability
        zones of the region, for example eu-west-par-a, eu-west-par-b and eu-west-par-c, and is
        empty for a single-AZ region. Models come smallest first, each sorted by region name. Use
        `name` as the model when creating a gateway.

        Args:
            project_id: Project ID
            name: Optional model filter, for example S (optional)
            region: Optional region filter, case-insensitive. Keeps the entries of this region only. A region that does not exist is rejected. One the project can neither use nor activate returns an empty list. (optional)

        Requires the IAM action publicCloudProject:apiovh:reference/gateway/model/get.
        """
        return self._pages(
            _r.OP_ALL_GATEWAY_MODELS,
            path_params={
                "projectId": project_id,
            },
            query=(
                ("name", name),
                ("region", region),
            ),
            item=models.PublicCloudReferenceGatewayModel,
        )

