    async def edit_load_balancer_pool_member(
        self,
        project_id: str,
        loadbalancer_id: str,
        pool_id: str,
        member_id: str,
        body: models.PublicCloudLoadbalancerMemberUpdate,
    ) -> models.PublicCloudLoadbalancerMember:
        """edit_load_balancer_pool_member calls PUT /v2/publicCloud/project/{projectId}/loadbalancer/{loadbalancerId}/pool/{poolId}/member/{memberId}: Update a pool member

        Replaces the member's target specification as a whole. The body carries the complete desired
        state of every field `publicCloud.loadbalancer.MemberUpdateTargetSpec` exposes — `backup`,
        `monitor`, `name` and `weight` — so read the member first and restate every value you want
        to keep: a field left out of `targetSpec` is cleared, not carried over from the stored
        specification.

        `monitor` is replaced as a whole, and so are the fields inside it. Leaving `monitor` out
        clears the health-monitoring override, and health monitoring falls back to the member's own
        address and protocol port. Sending a `monitor` that omits `address` or `port` clears just
        that one, and the member's own value is used for it.

        The create-only fields `address`, `protocolPort` and `subnet` cannot be changed once the
        member exists. They are deliberately absent from the update model, and sending one is
        rejected with a 400.

        The optional `checksum` guards against a lost update: when supplied it must match the
        member's current checksum or the request is rejected with a 409 checksum mismatch. Omitting
        it skips the check and forces the write (last-write-wins).

        Args:
            project_id: Project ID
            loadbalancer_id: Loadbalancer ID
            pool_id: Pool ID
            member_id: Member ID
            body: the request body

        Requires the IAM action publicCloudProject:apiovh:loadbalancer/pool/member/edit.
        """
        return await self._call(
            _r.OP_EDIT_LOAD_BALANCER_POOL_MEMBER,
            path_params={
                "projectId": project_id,
                "loadbalancerId": loadbalancer_id,
                "poolId": pool_id,
                "memberId": member_id,
            },
            body=body,
            body_type=models.PublicCloudLoadbalancerMemberUpdate,
            result=models.PublicCloudLoadbalancerMember,
        )

